INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 45, 'theory', 'Quiz: asyncio in practice');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 0, 'Which port do you pass to start_server so that the system picks any free one?', '["80", "0", "-1", "None"]', 1, 'Port 0 means any free port; the real number is taken from server.sockets[0].getsockname().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 1, 'Why are request retries made with a growing delay (backoff)?', '["It looks nicer", "Instant retries finish off an overloaded server; a pause lets it recover", "asyncio requires it", "To waste time"]', 1, 'The delay is usually doubled and some randomness is added so that clients do not knock at the same moment.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 2, 'Which class do you need to write coroutine tests (async def test_...)?', '["unittest.TestCase", "unittest.IsolatedAsyncioTestCase", "asyncio.TestCase", "doctest.AsyncCase"]', 1, 'Its methods run on a real event loop, and you can write await inside.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 3, 'What happens if you call time.sleep(5) in an async handler of a web server?', '["Only this request sleeps", "The whole server stops for 5 seconds", "Python raises an error", "Nothing"]', 1, 'A blocking call freezes the event loop; waiting goes to await, blocking work goes to threads.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 45, 4, 'What are contextvars for in asynchronous code?', '["For speed", "So each task has its own value of a variable (for example, a request id)", "For working with the network", "For timeouts"]', 1, 'Each task gets a copy of the context, and changes inside it are not visible to others.');
